<?php
namespace App\Http\Controllers;
use App\Models\{Employe,RhPaie};use App\Services\{AuditLogService,CurrentEntreprise,RhPaieWorkflowService,RhWorkflowService};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
use Barryvdh\DomPDF\Facade\Pdf;
class RhPaieController extends Controller{
 public function store(Request $r,RhPaieWorkflowService $s,RhWorkflowService $w){$d=$r->validate(['employe_id'=>'required_without:user_id|exists:rh_employes,id','user_id'=>'required_without:employe_id|nullable|exists:users,id','annee'=>'required|integer|min:2000|max:2100','mois'=>'required|integer|min:1|max:12','appliquer_retenue_absence'=>'nullable|boolean','motif_non_retenue_absence'=>'nullable|string|min:3','primes'=>'nullable|numeric|min:0','coefficient_heures_supplementaires'=>'nullable|numeric|min:1|max:10']);$e=!empty($d['employe_id'])?Employe::findOrFail($d['employe_id']):Employe::where('user_id',$d['user_id'])->firstOrFail();$this->sameCompany($r,$e);$old=RhPaie::where(['employe_id'=>$e->id,'annee'=>$d['annee'],'mois'=>$d['mois']])->first();if($old&&$old->statut!=='Brouillon')throw ValidationException::withMessages(['mois'=>'Une paie déjà calculée, validée ou payée ne peut pas être remplacée.']);$appliquer=$r->has('appliquer_retenue_absence')?$r->boolean('appliquer_retenue_absence'):true;$p=$s->calculer($e,$d['annee'],$d['mois'],$appliquer,$d['motif_non_retenue_absence']??null,$r->user()->id,$d);$w->trace($p,'calcul_paie',$r->user()->id,$d['motif_non_retenue_absence']??null,null,$p->toArray());return back()->with('success','Paie calculée depuis le contrat et la synthèse validée.');}
 public function storeAll(Request $r,RhPaieWorkflowService $service,RhWorkflowService $workflow){$d=$r->validate(['annee'=>'required|integer|min:2000|max:2100','mois'=>'required|integer|min:1|max:12','appliquer_retenues'=>'required|boolean','appliquer_retenue_absence'=>'required|boolean','motif_non_retenue_absence'=>'nullable|required_if:appliquer_retenue_absence,0|string|min:3|max:500']);$entreprise=app(CurrentEntreprise::class)->for($r->user());$employes=Employe::where('entreprise_id',$entreprise->id)->where('statut','Actif')->orderBy('nom')->get();$generes=0;$existants=0;$ignores=[];foreach($employes as $employe){try{$paie=RhPaie::where(['employe_id'=>$employe->id,'annee'=>$d['annee'],'mois'=>$d['mois']])->first();if(!$paie){$paie=$service->calculer($employe,$d['annee'],$d['mois'],(bool)$d['appliquer_retenue_absence'],$d['motif_non_retenue_absence']??null,$r->user()->id,['appliquer_retenues'=>(bool)$d['appliquer_retenues']]);$workflow->trace($paie,'calcul_paie_collectif',$r->user()->id,$d['motif_non_retenue_absence']??null,null,$paie->toArray());}else{$existants++;}if($paie->statut==='Calculée'){$avant=$paie->toArray();$paie->update(['statut'=>'Bulletin généré','bulletin_genere_le'=>now()]);$workflow->trace($paie,'generation_bulletin_collective',$r->user()->id,null,$avant,$paie->fresh()->toArray());$generes++;}}catch(ValidationException $exception){$ignores[]=$employe->matricule.' — '.collect($exception->errors())->flatten()->first();}}$message=$generes.' bulletin(s) généré(s) pour '.str_pad((string)$d['mois'],2,'0',STR_PAD_LEFT).'/'.$d['annee'].'.';if($existants)$message.=' '.$existants.' paie(s) existaient déjà.';$response=back()->with('success',$message);if($ignores)$response->with('warning',count($ignores).' employé(s) ignoré(s) : '.implode(' | ',$ignores));return $response;}
 public function downloadAll(Request $r){$d=$r->validate(['annee'=>'required|integer|min:2000|max:2100','mois'=>'required|integer|min:1|max:12']);$entreprise=app(CurrentEntreprise::class)->for($r->user());$paies=RhPaie::with(['employe.departement','employe.fonction','lignes'])->where('entreprise_id',$entreprise->id)->where('annee',$d['annee'])->where('mois',$d['mois'])->whereNotNull('employe_id')->whereIn('statut',['Bulletin généré','À vérifier','Validée','Prête au paiement','Payée','Clôturée'])->orderBy('employe_id')->get();if($paies->isEmpty())throw ValidationException::withMessages(['periode'=>'Aucun bulletin en ordre et généré pour cette période.']);foreach($paies as $paie)app(AuditLogService::class)->record('telechargement_bulletin_collectif_rh',$paie,(string)$paie->id,null,null,['format'=>'pdf','annee'=>$d['annee'],'mois'=>$d['mois']],[],$r);$nom='bulletins-paie-'.$d['annee'].'-'.str_pad((string)$d['mois'],2,'0',STR_PAD_LEFT).'.pdf';return Pdf::loadView('ressources_humaines.paie.bulletins-collectifs',compact('paies','entreprise'))->setPaper('a4')->download($nom);}
 public function edit(Request $r,RhPaie $paie){$this->superAdmin($r);$this->sameCompany($r,$paie);$this->modifiable($paie);$paie->load(['employe','contrat','syntheseMensuelle','lignes']);return view('ressources_humaines.paie.edit',compact('paie'));}
 public function update(Request $r,RhPaie $paie,RhWorkflowService $w){$this->superAdmin($r);$this->sameCompany($r,$paie);$this->modifiable($paie);$d=$r->validate(['salaire_base'=>'required|numeric|min:0','primes'=>'required|numeric|min:0','montant_heures_supplementaires'=>'required|numeric|min:0','retenues'=>'required|numeric|min:0','total_taxes'=>'required|numeric|min:0','total_cotisations'=>'required|numeric|min:0','monnaie'=>'required|in:CDF,USD','appliquer_retenue_absence'=>'required|boolean','motif_non_retenue_absence'=>'nullable|required_if:appliquer_retenue_absence,0|string|min:3','commentaire'=>'nullable|string','motif_modification'=>'required|string|min:5']);$g=(float)$d['salaire_base']+(float)$d['primes']+(float)$d['montant_heures_supplementaires'];$ret=(float)$d['retenues']+(float)$d['total_taxes']+(float)$d['total_cotisations'];if($ret>$g)throw ValidationException::withMessages(['retenues'=>'Les retenues ne peuvent pas dépasser les gains.']);$old=$paie->toArray();$snap=$paie->instantane_calcul??[];$snap['derniere_modification']=['auteur'=>$r->user()->id,'date'=>now()->toIso8601String(),'motif'=>$d['motif_modification'],'anciennes_valeurs'=>$old];$data=$d+['modifie_par'=>$r->user()->id,'modifie_le'=>now(),'instantane_calcul'=>$snap];if(in_array($paie->statut,['Validée','Prête au paiement'],true))$data+=['statut'=>'À vérifier','valide_par'=>null,'valide_le'=>null];DB::transaction(fn()=>$paie->update($data));$fresh=$paie->fresh();$w->trace($fresh,'modification_manuelle_paie',$r->user()->id,$d['motif_modification'],$old,$fresh->toArray());app(AuditLogService::class)->record('modification_manuelle_paie_rh',$fresh,(string)$fresh->id,$d['motif_modification'],$old,$fresh->toArray(),[],$r);return redirect()->route('parametres.rh.paie')->with('success','Paie modifiée et tracée.'.($fresh->statut==='À vérifier'?' Une nouvelle validation est requise.':''));}
 public function transition(Request $r,RhPaie $p,RhWorkflowService $w){$this->sameCompany($r,$p);$d=$r->validate(['statut'=>'required|in:Bulletin généré,À vérifier,Validée,Prête au paiement,Clôturée','motif'=>'nullable|string']);$map=['Calculée'=>['Bulletin généré'],'Bulletin généré'=>['À vérifier'],'À vérifier'=>['Validée'],'Validée'=>['Prête au paiement'],'Payée'=>['Clôturée']];$changes=match($d['statut']){'Bulletin généré'=>['bulletin_genere_le'=>now()],'Validée'=>['valide_par'=>$r->user()->id,'valide_le'=>now()],'Clôturée'=>['cloture_le'=>now()],default=>[]};$w->transition($p,$d['statut'],$map,$r->user()->id,$d['motif']??null,$changes);return back()->with('success','Workflow de paie mis à jour.');}
 private function superAdmin(Request $r):void{abort_unless($r->user()?->isSuperAdmin(),403);}private function modifiable(RhPaie $p):void{if(in_array($p->statut,['Payée','Clôturée'],true))throw ValidationException::withMessages(['paie'=>'Une paie payée ou clôturée ne peut plus être modifiée.']);}private function sameCompany(Request $r,$m):void{abort_unless((int)$m->entreprise_id===(int)app(CurrentEntreprise::class)->for($r->user())->id,404);}
}
